         float amzLocal_time = 0.0;
         float duration = 7.0;
         float atime = 2.0;
         const int type = 1;
         float random(float2 par){
            return fract(sin(dot(par.xy,float2(12.9898,78.233))) * 43758.5453);
         }
         float2 random2(float2 par){
          float rand = random(par);
          return float2(rand, random(par+rand));
         }
         float4 filte(float2 uv) {
             float2 uvo = uv;
             float2 point[12];
             for(int i = 0; i< int(amzp_AMOUNT); i++) {
                 point[i] = random2(float2(float(i)));
             }
             float m_dist = 10000.0;
             float id = 0.0;
             float4 col = float4(0.);
             for (int i = 0; i < int(amzp_AMOUNT); i++) {
                 float2 dir = normalize( point[i] - float2(0.5) ) ;
                 float v = (.5 + random(dir)*.5) * .2 ;
                 float2 ofst = dir * v * amzLocal_time ;
