                 float m_dist = distance(U, point[i]);
                 bool match = true;
                 if(U.x > 0.0 && U.x < 1.0 && U.y > 0.0 && U.y < 1.0 ) {
                     for(int j = 0; j < int(amzp_AMOUNT); j++) {
                         float dist = distance(U, point[j]);
                         if(dist < m_dist) match = false;
                     }
                 }else {
                     match = false;
                 }
